#ifndef XENIA_UI_KIWI_FRAME_GEN_STATS_H_
#define XENIA_UI_KIWI_FRAME_GEN_STATS_H_

#include <atomic>
#include <cstdint>

namespace xe {
namespace ui {

// Frames generated by frame generation, for the performance HUD (the game's
// own frames are counted by the GPU emulation).
struct KiwiFrameGenStats {
  std::atomic<uint64_t> generated_frames{0};
};

inline KiwiFrameGenStats& GetKiwiFrameGenStats() {
  static KiwiFrameGenStats stats;
  return stats;
}

}  // namespace ui
}  // namespace xe

#endif  // XENIA_UI_KIWI_FRAME_GEN_STATS_H_
